// ── Deduplicate by URL using workflow-persistent static data ──
// Static data survives between executions without any external DB.
const staticData = $getWorkflowStaticData('global');
if (!staticData.seenUrls) staticData.seenUrls = [];

const seenSet = new Set(staticData.seenUrls);
const allItems = $input.all();

// Normalise fields across different RSS feed schemas
const newItems = allItems
  .filter(item => !item.json.error)  // drop failed RSS fetches
  .map(item => {
    const j = item.json;
    return {
      json: {
        title:          (j.title || 'Untitled').trim(),
        link:           (j.link || j.url || j.guid || '').trim(),
        contentSnippet: (j.contentSnippet || j.content || j.description || '').replace(/<[^>]+>/g, '').substring(0, 1500),
        pubDate:        j.pubDate || j.isoDate || new Date().toISOString(),
        source:         j.creator || j.author || j['dc:creator'] || 'Unknown',
      }
    };
  })
  .filter(item => item.json.link && !seenSet.has(item.json.link));

if (newItems.length === 0) {
  // Nothing new — return empty array to halt downstream nodes gracefully
  return [];
}

return newItems;

// Mark this URL as seen immediately so a later failure won't cause a re-post.
// We cap the list at 2 000 entries to prevent unbounded static-data growth.
const staticData = $getWorkflowStaticData('global');
if (!staticData.seenUrls) staticData.seenUrls = [];

const url = $json.link;
if (url && !staticData.seenUrls.includes(url)) {
  staticData.seenUrls.push(url);
  if (staticData.seenUrls.length > 2000) {
    staticData.seenUrls = staticData.seenUrls.slice(-2000);
  }
}

return { json: $json };

// Parse the AI JSON response and merge back with the original article fields.
// The OpenAI node replaces item data with the AI response, so we re-attach
// the original article via the named-node reference $('Mark All Seen').item.json
const aiText = (
  $json.content              // simplifyOutput:true  → {content: '...'}
  || $json.message?.content  // some n8n versions    → {message: {content: '...'}}
  || $json.choices?.[0]?.message?.content  // raw OpenAI shape
  || ''
).trim();

const originalArticle = $('Mark All Seen').item.json;

let parsed = { score: 0, reason: 'Could not parse AI response', summary: '' };
try {
  const match = aiText.match(/\{[\s\S]*\}/);
  if (match) parsed = JSON.parse(match[0]);
} catch (_) { /* keep safe defaults */ }

const score = Math.min(10, Math.max(0, Number(parsed.score) || 0));

return {
  json: {
    ...originalArticle,
    score,
    reason:  String(parsed.reason  || 'No reason provided').substring(0, 120),
    summary: String(parsed.summary || originalArticle.contentSnippet || '').substring(0, 300),
  }
};

// Build the Discord embed payload.
// Colors: red (9-10) → orange (8) → gold (7)
const score = $json.score || 0;
const color = score >= 9 ? 15158332 : score === 8 ? 16744272 : 16776960;

const scoreBar = '█'.repeat(score) + '░'.repeat(10 - score);

const embed = {
  title:       String($json.title || 'Crypto News').substring(0, 256),
  description: String($json.summary || '').substring(0, 4096),
  url:         $json.link || '',
  color,
  fields: [
    {
      name:   '🎯 Relevance',
      value:  `**${score}/10**  \`${scoreBar}\``,
      inline: true
    },
    {
      name:   '📰 Source',
      value:  String($json.source || 'Unknown').substring(0, 256),
      inline: true
    },
    {
      name:   '💡 Why It Matters',
      value:  String($json.reason || 'No reason provided').substring(0, 1024),
      inline: false
    }
  ],
  footer: {
    text: 'AlphaForgeAI Crypto Intel'
  },
  timestamp: new Date().toISOString()
};

return {
  json: {
    ...$json,
    discordPayload: JSON.stringify({ embeds: [embed] })
  }
};

// Verify the Discord post succeeded (HTTP 2xx).
// If it failed, log the error but do NOT re-add the URL to seenUrls
// so the article can be retried on the next run.
const statusCode = $json.statusCode || 200;
if (statusCode >= 400) {
  const staticData = $getWorkflowStaticData('global');
  const url = $json.link;
  if (url && staticData.seenUrls) {
    staticData.seenUrls = staticData.seenUrls.filter(u => u !== url);
  }
  throw new Error(`Discord returned HTTP ${statusCode} — URL removed from seen list for retry`);
}
return { json: $json };
